from lezione_testi_cg import S

TITOLO = "Indici e margini: struttura, situazione e ciclo monetario"
INTRO = """Adesso che il bilancio è riclassificato, lo facciamo parlare con gli indicatori. In questo capitolo vedi la differenza tra indice e margine, gli indici di struttura, quelli di situazione finanziaria e infine il ciclo monetario, che negli appunti è definito l'elemento più dinamico del corso. Sono tante formule, ma sono quasi tutte rapporti tra le stesse lettere: F, C, N, K. Se ti ricordi cosa significano, le formule le ricostruisci da solo."""

